-- Seed data. Generated from real Fauxnance daily candles (run on 2026-10-07), so every price below is a real close.
-- Every FILLED order is priced at that day's close; cash moves exactly as settlement moves it (a dollar fill is
-- converted to rupees at that day's USD/INR close with the 0.5% order margin, and keeps its rate in fx_rate), and
-- positions use the weighted-average-cost rule, so orders, trades, the cash ledger, positions and balances agree.
-- The ledger-reconciliation check in checks/ should come back empty.

-- ------------------------------------------------------------------ instruments
-- 50 NSE, 50 US (stocks and ETFs), 25 crypto, plus FX pairs and one delisted share.

-- ------------------------------------------------------------------ accounts (cash is set last, from the ledger)

-- ------------------------------------------------------------------ orders

-- ------------------------------------------------------------------ positions (in each instrument's own currency)

-- ------------------------------------------------------------------ trades (one per FILLED order; fx_rate set for dollar instruments)

-- ------------------------------------------------------------------ cash ledger (deposits, withdrawals and one row per trade)

-- ------------------------------------------------------------------ exchange rates (the executor refreshes these daily)

-- ------------------------------------------------------------------ latest prices for held and watched symbols
-- Marked stale: they are the last real close, and the market-data poller replaces them with live quotes.

-- ------------------------------------------------------------------ preferences

-- ------------------------------------------------------------------ watchlists


-- ------------------------------------------------------------------ price alerts

SELECT a.id, v.last_price, '2026-10-07 10:00:00' FROM price_alerts a
JOIN accounts ac ON ac.id = a.account_id
JOIN (VALUES ('ETP-4101', 'TCS.NS', 'BELOW', 2000.00::numeric, 2080.3000::numeric), ('ETP-4101', 'MSFT', 'ABOVE', 560.00::numeric, 529.7600::numeric), ('ETP-4101', 'X:ETH-USD', 'ABOVE', 2500.00::numeric, 2668.4620::numeric), ('ETP-4102', 'NVDA', 'ABOVE', 230.00::numeric, 237.4700::numeric), ('ETP-4102', 'AAPL', 'BELOW', 180.00::numeric, 336.6700::numeric), ('ETP-4103', 'KOTAKBANK.NS', 'ABOVE', 2300.00::numeric, 440.0000::numeric), ('ETP-4104', 'X:SOL-USD', 'ABOVE', 300.00::numeric, 121.1603::numeric), ('ETP-4104', 'X:NEAR-USD', 'ABOVE', 7.00::numeric, 5.1051::numeric)) AS v(ref, symbol, direction, target, last_price)
  ON ac.account_id = v.ref AND a.symbol = v.symbol AND a.direction = v.direction AND a.target_price = v.target;

